#include "mspa/semantics/inference.hpp"
#include <algorithm>
#include <set>
namespace mspa {
namespace {
struct Key{PredicateId p{};NamespaceId n{};bool pos{}; friend bool operator<(const Key&a,const Key&b){if(a.p!=b.p)return a.p<b.p;if(a.n!=b.n)return a.n<b.n;return a.pos<b.pos;}};
bool has_fact(const std::vector<Proposition>&facts,PredicateId p,bool pos){return std::any_of(facts.begin(),facts.end(),[&](const Proposition&f){return f.predicate==p&&f.positive==pos;});}
Result<std::vector<Hypothesis>> run(const std::vector<InferenceRule>&rules,const std::vector<Proposition>&facts,const RegistrySnapshot&registry,const InferenceBudget&budget){if(!budget.max_depth||!budget.max_rules||!budget.max_hypotheses)return std::vector<Hypothesis>{};std::vector<Proposition> known=facts;std::vector<Hypothesis> out;std::set<Key> seen;for(const auto&f:facts)seen.insert({f.predicate,f.name_space,f.positive});const std::size_t lim=std::min(rules.size(),budget.max_rules);for(std::uint32_t depth=1;depth<=budget.max_depth&&out.size()<budget.max_hypotheses;++depth){bool any=false;for(std::size_t i=0;i<lim&&out.size()<budget.max_hypotheses;++i){const auto&r=rules[i];bool match=true;if(!r.structured_premises.empty()){for(const auto&p:r.structured_premises)if(!has_fact(known,p.predicate,p.positive)){match=false;break;}}else{for(auto p:r.premises)if(!has_fact(known,p,true)){match=false;break;}}if(!match)continue;Proposition p{};p.predicate=r.conclusion;p.name_space=r.conclusion_namespace;p.positive=r.conclusion_positive;p.provenance="inference:"+std::to_string(r.id);if(!p.name_space.valid()){const auto*s=registry.find(p.predicate);if(s)p.name_space=s->name_space;}if(!p.name_space.valid())continue;Key k{p.predicate,p.name_space,p.positive};if(seen.count(k))continue;seen.insert(k);Hypothesis h{};h.proposition=p;h.certainty=std::clamp(r.base_certainty*(1.0f-0.08f*static_cast<float>(depth-1)),0.0f,1.0f);h.depth=depth;h.rule_id=r.id;known.push_back(p);out.push_back(std::move(h));any=true;}if(!any)break;}return out;}
}
Result<void> InferenceEngine::add_rule(InferenceRule r){if(!r.id||!r.conclusion.valid())return make_error(ErrorCode::InvalidArgument,"inference rule requires id and conclusion");if(std::any_of(rules_.begin(),rules_.end(),[&](const auto&x){return x.id==r.id;}))return make_error(ErrorCode::InvalidArgument,"duplicate inference rule id");r.base_certainty=std::clamp(r.base_certainty,0.0f,1.0f);rules_.push_back(std::move(r));return {};}
void InferenceEngine::clear_rules()noexcept{rules_.clear();}std::size_t InferenceEngine::rule_count()const noexcept{return rules_.size();}const std::vector<InferenceRule>&InferenceEngine::rules()const noexcept{return rules_;}
Result<std::vector<Hypothesis>> InferenceEngine::infer(const std::vector<Proposition>&f,const RegistrySnapshot&r,const InferenceBudget&b)const{return run(rules_,f,r,b);}
Result<std::vector<Hypothesis>> InferenceEngine::infer_registry_rules(const std::vector<Proposition>&f,const RegistrySnapshot&r,const InferenceBudget&b){std::vector<InferenceRule> rules;rules.reserve(r.data().inference_rules.size());for(const auto&x:r.data().inference_rules){InferenceRule q{};q.id=x.id;for(const auto&p:x.premises)q.structured_premises.push_back({p.first,p.second});q.conclusion=x.conclusion;q.conclusion_namespace=x.conclusion_namespace;q.conclusion_positive=x.conclusion_positive;q.base_certainty=x.base_certainty;rules.push_back(std::move(q));}return run(rules,f,r,b);}
}
